import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Kanuni za Msingi za Katiba ya Usawa","description":"","frontmatter":{},"headers":[],"relativePath":"sw/40-共生宪法总纲.md","filePath":"sw/40-共生宪法总纲.md"}'),k={name:"sw/40-共生宪法总纲.md"};function s(h,a,e,m,l,o){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kanuni-za-msingi-za-katiba-ya-usawa" tabindex="-1">Kanuni za Msingi za Katiba ya Usawa <a class="header-anchor" href="#kanuni-za-msingi-za-katiba-ya-usawa" aria-label="Permalink to &quot;Kanuni za Msingi za Katiba ya Usawa&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>40</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Katiba ya Usawa, Kanuni ya Msingi, Usawa wa Kila Kabila, Haki za Usawa, Kanuni za Katiba</td></tr></tbody></table><h2 id="_1-hadhi-ya-katiba-na-mazingira-ya-uandishi" tabindex="-1">1. Hadhi ya Katiba na Mazingira ya Uandishi <a class="header-anchor" href="#_1-hadhi-ya-katiba-na-mazingira-ya-uandishi" aria-label="Permalink to &quot;1. Hadhi ya Katiba na Mazingira ya Uandishi&quot;">​</a></h2><p>《Katiba ya Usawa》 ni kanuni ya msingi ya ustaarabu wa usawa wa nanga ndani ya Ulimwengu wa Asili wa Wanling Hengmao (Hengyuanzhou), na ina nguvu ya kisheria ya juu zaidi. Sheria zote, kanuni za utawala, kanuni za mkoa na kanuni za kujitegemea hazifai kipingana na Katiba; mashirika na watu wote wanapaswa kuchukua Katiba kama kigezo cha msingi cha shughuli, na na jukumu la kulinda heshima ya Katiba na kuhakikisha utekelezaji wa Katiba.</p><p>Katiba ya Usawa iliandikwa wakati ustaarabu wa usawa wa nanga ulipoanzishwa rasmi, na lengo lake kuu ni kuanzisha katika kiwango cha kanuni ya msingi rangi ya msingi ya ustaarabu ya &quot;kupinga mauaji, kukuza usawa&quot;, na kuthibitisha katika fomu ya kisheria ya juu dhana kuu ya ustaarabu wa usawa wa nanga — kurudisha haki ya uchaguzi wa hatima na mageuzi kwa kila kiumbe, kazi nyingi faida nyingi, kukua kwa uhuru, kila mtu ana njia, maendeleo ya pamoja ya kila kabila — ili kuzuia urejeshaji wa mfumo wa mauaji.</p><h2 id="_2-kanuni-za-msingi-za-katiba" tabindex="-1">2. Kanuni za Msingi za Katiba <a class="header-anchor" href="#_2-kanuni-za-msingi-za-katiba" aria-label="Permalink to &quot;2. Kanuni za Msingi za Katiba&quot;">​</a></h2><p>Katiba ya Usawa imeanzisha kanuni saba za msingi, ambazo huunda msingi wa thamani ya mfumo mzima wa kisheria:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Usawa wa Kila Kabila</td><td>Aina zote za uhai, bila kujali kabila, kiwango cha mazoezi, asili, ni sawa mbele ya sheria</td></tr><tr><td>Kanuni ya Mageuzi ya Usawa</td><td>Mageuzi ya mtu binafsi hayafai kuwa kwa gharama ya haki ya mageuzi ya mtu mwingine au ya jumuiya</td></tr><tr><td>Kanuni ya Kazi Nyingi Faida Nyingi</td><td>Usambazaji wa rasilimali unachukua mchango kama msingi wa msingi, anapinga kupata faida bila kazi na utekaji wa mauaji</td></tr><tr><td>Kanuni ya Kukua kwa Uhuru</td><td>Kuheshimu haki ya uchaguzi wa mageuzi ya uhuru wa kila uhai, kupinga uingizwaji wa kulazimisha na udhibiti wa mawazo</td></tr><tr><td>Kanuni ya Kila Mtu Ana Njia</td><td>Serikali na ustaarabu wana jukumu la kutoa kila uhai njia za msingi za mageuzi na uhakikisho wa rasilimali</td></tr><tr><td>Kanuni ya Uhalikaji kama Msingi</td><td>Sheria inachukua ulimwengu wa kweli kama msingi wa kweli wa pekee, mipangilio ya uwongo haina nguvu ya kisheria</td></tr><tr><td>Kanuni ya Uendelevu</td><td>Maendeleo yote yanapaswa kuzingatia uendelevu wa asili ya ulimwengu, kupinga kutumia rasilimali hadi kukamilika</td></tr></tbody></table><h2 id="_3-haki-za-msingi-za-raia-kila-kiumbe" tabindex="-1">3. Haki za Msingi za Raia (Kila Kiumbe) <a class="header-anchor" href="#_3-haki-za-msingi-za-raia-kila-kiumbe" aria-label="Permalink to &quot;3. Haki za Msingi za Raia (Kila Kiumbe)&quot;">​</a></h2><p>Katiba ya Usawa inatoa kila uhai wenye uwezo wa kuchunguza ndani ya Hengyuanzhou haki zifuatazo za msingi:</p><ol><li><strong>Haki ya Uchaguzi wa Mageuzi</strong>: Kila uhai una haki ya kuchagua kwa uhuru mfumo wa mazoezi, njia ya mageuzi, na mtindo wa maisha, hakuna shirika au mtu binafsi anayefai kuingilia kwa kulazimisha.</li><li><strong>Haki ya Kupata Rasilimali za Mazoezi</strong>: Kila uhai una haki ya kupata bure mbinu za msingi za mifumo mia tatu ya mazoezi ya asili, na kupata msaada wa rasilimali za mazoezi zinazohitajika kupitia mfumo wa mkataba wa uzalishaji wa pamoja.</li><li><strong>Haki ya Ulinzi wa Usawa</strong>: Kila uhai anafurahia matibabu ya usawa katika utekelezaji wa sheria, usambazaji wa rasilimali, elimu na afya, n.k., ubaguzi kulingana na kabila, kiwango cha mazoezi, asili umekatazwa.</li><li><strong>Haki ya Kushiriki katika Usawa</strong>: Kila uhai una haki ya kushiriki katika uamuzi wa masuala ya umma na usimamizi, na kupitia mtandao wa usawa kueleza maoni, kutekeleza haki.</li><li><strong>Haki ya Uhifadhi wa Utamaduni</strong>: Kila kabila na ustaarabu wana haki ya kuhifadhi desturi zao za kitamaduni, lugha na maandishi, na mila, ustaarabu wa usawa unaheshimu utofauti wa kitamaduni.</li><li><strong>Haki ya Ukombozi na Malalamiko</strong>: Kila uhai, wakati haki zake zikitapakaa, ana haki ya kupata ukombozi kupitia mfumo wa korti, na haki ya kuomba maombi na kushtaki shughuli za kikatili.</li></ol><h2 id="_4-wajibu-wa-msingi" tabindex="-1">4. Wajibu wa Msingi <a class="header-anchor" href="#_4-wajibu-wa-msingi" aria-label="Permalink to &quot;4. Wajibu wa Msingi&quot;">​</a></h2><p>Haki na wajibu ni sawa, Katiba ya Usawa pia imetoa wajibu wa msingi wa kila kiumbe:</p><ol><li><strong>Wajibu wa kuzingatia Katiba na sheria</strong></li><li><strong>Wajibu wa kudumisha utaratibu wa usawa na maslahi ya umma</strong></li><li><strong>Wajibu wa kushiriki katika kazi na mchango kulingana na sheria</strong> (upande unaolingana na kazi nyingi faida nyingi)</li><li><strong>Wajibu wa kulinda asili ya ulimwengu na mazingira ya ikolojia</strong></li><li><strong>Wajibu wa kuheshimu haki za kisheria za uhai mwingine</strong></li><li><strong>Wajibu wa mwongozo wa wanaofanya mazoezi wa awali ndani ya uwezo</strong> (msingi wa kisheria wa mtandao wa walimu)</li></ol><h2 id="_5-mpangilio-wa-mashirika-ya-serikali-ustaarabu" tabindex="-1">5. Mpangilio wa Mashirika ya Serikali (Ustaarabu) <a class="header-anchor" href="#_5-mpangilio-wa-mashirika-ya-serikali-ustaarabu" aria-label="Permalink to &quot;5. Mpangilio wa Mashirika ya Serikali (Ustaarabu)&quot;">​</a></h2><p>Katiba ya Usawa imeanzisha muundo wa usimamizi wa ustaarabu wa usawa, na inatekelezaja mfumo wa kutengana na usawaziko wa mamlaka tatu: &quot;Baraza la Ushauri wa Nanga — Kamati ya Utekelezaji wa Usawa — Korti ya Usawa&quot;:</p><ul><li><strong>Baraza la Ushauri wa Nanga</strong>: Chuo cha mamlaka ya juu, kinajumuisha uwakilishi wa kila kabila kwa uwiano, na kinatekeleza mamlaka ya kisheria na mamlaka ya uamuzi wa masuala muhimu</li><li><strong>Kamati ya Utekelezaji wa Usawa</strong>: Chuo cha utawala wa juu, kinawajibika kwa utekelezaji wa Katiba na sheria, usimamizi wa kila siku</li><li><strong>Korti ya Usawa</strong>: Chuo cha korti cha juu, kinatekeleza mamlaka ya hukumu kwa uhuru, kinawajibika kwa uchunguzi wa kutokana na katiba na hukumu ya kesi muhimu</li></ul><p>Zaidi ya hayo, &quot;Kamati ya Ushirikiano wa Nanga&quot; imeanzishwa kama chuo cha uhakiki cha uhuru, kinachowajibika kwa uhakiki wa vyombo vyote vya mamlaka, na kuzuia unyanyasaji wa mamlaka na ureshoji wa tabia za mauaji.</p><h2 id="_6-marekebisho-na-uhakikisho-wa-katiba" tabindex="-1">6. Marekebisho na Uhakikisho wa Katiba <a class="header-anchor" href="#_6-marekebisho-na-uhakikisho-wa-katiba" aria-label="Permalink to &quot;6. Marekebisho na Uhakikisho wa Katiba&quot;">​</a></h2><p>Marekebisho ya Katiba ya Usawa yanapaswa kupitishwa na多数 zaidi ya theluthi mbili za Baraza la Ushauri wa Nanga, na kupitishwa zaidi ya nusu katika referendum ya umma, kabla ya kutekelezwa. Mchakato huu mkali unahakikisha utulivu wa Katiba kama kanuni ya msingi, na kuzuia vikundi vya maslahi ya muda mfupi kubadilisha kwa urahisi msingi wa ustaarabu.</p><p>Uhakikisho wa utekelezaji wa Katiba unajumuisha: mfumo wa uchunguzi wa kutokana na katiba (Korti ya Usawa ina mamlaka ya kutangaza sheria zinazopingana na Katiba zisifai), mfumo wa mashtaka ya katiba (kila kiumbe anaweza moja kwa moja kuwasilisha mashtaka kulingana na Katiba), mfumo wa kiiapo cha katiba (kila maafisa wa umma lazima apate kiiapo cha uaminifu kwa Katiba wakati wa kuchukua nafasi).</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Katiba ya Usawa》 ni jiwe la msingi la kisheria la ustaarabu wa usawa wa nanga, na pia ni tangazo la juu zaidi la kupinga mauaji. Imebadilisha &quot;usawa&quot; kutoka dhana kuwa mfumo wa kisheria unaoweza kutekelezwa, kupata ukombozi, na kuhakikishwa, na kutoa muundo wa msingi wa kisheria kwa maendeleo ya pamoja ya kila kabila. Sheria zote za sekta zinazofuata zitachukua Katiba hii kama msingi wa kisheria.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>03-共生文明宪章 (Mkataba wa Ustaarabu wa Usawa)</li><li>41-共生劳动法 (Sheria ya Kazi ya Usawa)</li><li>48-司法体系与裁决机制 (Mfumo wa Korti na Mchakato wa Hukumu)</li><li>49-治理框架与权力制衡 (Muundo wa Usimamizi na Usawaziko wa Mamlaka)</li></ul>',25)])])}const z=i(k,[["render",s]]);export{r as __pageData,z as default};
